    update public.projects set sort_order=sort_order+1 where sort_order>=project_order;
    insert into public.projects(id,data,sort_order,is_visible)
    values('20000000-0000-4000-8000-000000000003','{"title":"Cliped","slug":"cliped","category":"Visión por computadora · Fútbol","category_en":"Computer vision · Football","year":"2026","status":"En desarrollo","featured":false,"is_demo":false,"cover":"/projects/cliped.svg","screenshots":[],"video":"","github":"","demo":"","technologies":["React","TypeScript","Python","FastAPI","OpenVINO"],"short_description":"Tracker de jugadores de fútbol: analiza videos, permite seleccionar un perfil visual y exporta el seguimiento del jugador con audio.","short_description_en":"Football player tracker: analyzes videos, lets you select a visual profile and exports the selected player''s tracking with audio.","long_description":"Aplicación en desarrollo para seguir a un jugador en videos de fútbol. El MVP funciona localmente en Windows: se carga un MP4, se analiza el video completo y se elige un jugador desde una galería de perfiles visuales. A partir de esa selección se genera un video con el seguimiento y el audio original.","long_description_en":"An application in development for tracking a player in football videos. The MVP runs locally on Windows: upload an MP4, analyze the complete video and select a player from a gallery of visual profiles. That selection is used to generate a tracking video with the original audio.","problem":"Seguir a una misma persona durante un partido grabado, incluso cuando cambia de posición, se aleja de la cámara o se cruza con otros jugadores.","problem_en":"Follow the same person throughout a recorded match, including position changes, movement away from the camera and crossings with other players.","solution":"Detección de personas, análisis de postura y comparación de apariencia para construir perfiles y trayectorias. La interfaz permite elegir el jugador, agregar referencias manuales cuando está lejos y exportar su seguimiento. Los intervalos ambiguos quedan sin marcar.","solution_en":"Person detection, pose analysis and appearance comparison build visual profiles and trajectories. The interface lets you select a player, add manual references when they are far away and export their tracking. Ambiguous intervals are left unmarked.","architecture":"Frontend con React, TypeScript y Vite, conectado a una API FastAPI en Python. El análisis utiliza YOLO11n, YOLO11n-Pose y OSNet mediante OpenVINO, con OpenCV para el procesamiento de video. FFmpeg exporta el MP4 final con las marcas del jugador y conserva el audio. Los archivos y metadatos se almacenan localmente.","architecture_en":"A React, TypeScript and Vite frontend connected to a Python FastAPI API. Analysis uses YOLO11n, YOLO11n-Pose and OSNet through OpenVINO, with OpenCV for video processing. FFmpeg exports the final MP4 with player annotations and preserved audio. Files and metadata are stored locally.","challenges":"Mantener la identidad ante oclusiones, jugadores pequeños y ropa similar, y optimizar el análisis de videos completos. La identificación a distancia y la consistencia de los perfiles siguen en evaluación; el sistema admite correcciones asistidas.","challenges_en":"Maintain identity through occlusions, small players and similar clothing, and optimize full-video analysis. Distant identification and profile consistency remain under evaluation; the system supports assisted corrections.","results":"MVP local con carga de videos, galería de perfiles, selección de jugador y exportación del seguimiento con audio. Sigue en desarrollo: la precisión de identidad y el rendimiento requieren más validación. El alcance actual es el seguimiento visual, sin estadísticas deportivas ni identificación por nombre.","results_en":"A local MVP with video upload, a profile gallery, player selection and tracking export with audio. Development continues: identity accuracy and performance require further validation. The current scope is visual tracking, without sports statistics or identification by name."}'::jsonb,project_order,true);
  end if;
